import { PrismaClient } from "@prisma/client";
import fs from "fs";
import path from "path";

function getDatabaseUrl(): string | undefined {
  if (process.env.DATABASE_URL && !process.env.DATABASE_URL.startsWith("file:")) {
    return process.env.DATABASE_URL;
  }

  if (process.env.VERCEL) {
    const tmpDbPath = "/tmp/dev.db";
    const srcDb = path.join(process.cwd(), "prisma", "dev.db");
    if (!fs.existsSync(/*turbopackIgnore: true*/ tmpDbPath)) {
      if (fs.existsSync(/*turbopackIgnore: true*/ srcDb)) {
        try {
          fs.copyFileSync(srcDb, tmpDbPath);
        } catch (e) {
          console.error("Failed to copy db to /tmp:", e);
        }
      }
    }
    return "file:/tmp/dev.db";
  }

  return process.env.DATABASE_URL || "file:./dev.db";
}

const prismaClientSingleton = () => {
  const dbUrl = getDatabaseUrl();
  return new PrismaClient({
    datasources: dbUrl ? { db: { url: dbUrl } } : undefined,
  });
};

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

export const prisma = globalForPrisma.prisma ?? prismaClientSingleton();

if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

import { prisma } from "@/lib/prisma";

export interface AuthenticatedParent {
  id: string;
  name: string;
  phone: string;
  email?: string | null;
  notes?: string | null;
  students: any[];
}

/**
 * Extracts and verifies parent identity from request headers.
 * Supports:
 * 1. "Per-User Token (BFF-injected, Orchexa relays)": Bearer token containing parent ID/phone
 * 2. "User Context (Signed actor, Partner-side RBAC)": x-parent-phone or x-parent-id
 */
export async function getParentFromRequest(request: Request): Promise<AuthenticatedParent | null> {
  const authHeader = request.headers.get("authorization");
  const parentIdHeader = request.headers.get("x-parent-id");
  const parentPhoneHeader = request.headers.get("x-parent-phone");

  // Check custom headers (User Context mode)
  if (parentIdHeader) {
    const parent = await prisma.parent.findUnique({
      where: { id: parentIdHeader },
      include: { students: { include: { classes: { include: { course: true } } } } }
    });
    if (parent) return parent;
  }

  if (parentPhoneHeader) {
    const parent = await prisma.parent.findUnique({
      where: { phone: parentPhoneHeader },
      include: { students: { include: { classes: { include: { course: true } } } } }
    });
    if (parent) return parent;
  }

  // Check Bearer token (Per-User Token mode)
  if (authHeader && authHeader.startsWith("Bearer ")) {
    const token = authHeader.substring(7).trim();
    // Allow tokens formatted as "parent_<id>", "phone_<phone>", or raw phone/id
    const cleanToken = token.replace(/^(parent_|phone_|jwt_)/, "");

    const parent = await prisma.parent.findFirst({
      where: {
        OR: [
          { id: cleanToken },
          { phone: cleanToken },
          { phone: token }
        ]
      },
      include: { students: { include: { classes: { include: { course: true } } } } }
    });
    if (parent) return parent;
  }

  return null;
}

import crypto from 'crypto'

const DEFAULT_CLIENT_ID = 'ocx_client_b4b15422d65cc136acab8ec5'
const DEFAULT_AGENT_ID = '911aa67c-1a89-4418-ac9e-f451c51a0629'
const DEFAULT_API_BASE = 'https://api.orchexa.io'
const PATH = '/api/v1/embedded/sessions'

export interface CreateOrchexaSessionOptions {
  resumeLast?: boolean
  conversationId?: string
  /** Customer profile from your CRM — orders/students/attendance/tickets/etc.
   *  Passed as initial_context.customer or initialContext so the AI knows the caller
   *  before their first message. */
  customerProfile?: Record<string, unknown>
  initialContext?: Record<string, unknown>
}

export async function createOrchexaSession(
  externalUserId: string,
  externalTenantId: string,
  opts: CreateOrchexaSessionOptions = { resumeLast: true }
) {
  const clientId = process.env.ORCHEXA_CLIENT_ID || DEFAULT_CLIENT_ID
  const clientSecret = process.env.ORCHEXA_CLIENT_SECRET
  const agentId = process.env.ORCHEXA_AGENT_ID || DEFAULT_AGENT_ID
  const apiBase = (process.env.ORCHEXA_API_BASE || DEFAULT_API_BASE).replace(/\/$/, '')

  if (!clientSecret || clientSecret.includes('<paste')) {
    throw new Error(
      'ORCHEXA_CLIENT_SECRET is not configured or still contains placeholder. Please set a valid ORCHEXA_CLIENT_SECRET in your .env.'
    )
  }

  const bodyObj: Record<string, unknown> = {
    agent_id: agentId,
    external_user_id: externalUserId,
    external_tenant_id: externalTenantId,
    channel: 'crm_web',
    resume_last: opts.resumeLast !== false,
  }
  if (opts.conversationId) bodyObj.conversation_id = opts.conversationId
  if (opts.initialContext) {
    bodyObj.initial_context = opts.initialContext
  } else if (opts.customerProfile) {
    bodyObj.initial_context = { customer: opts.customerProfile }
  }

  const body = JSON.stringify(bodyObj)
  const ts = Math.floor(Date.now() / 1000).toString()
  const bodyHash = crypto.createHash('sha256').update(body).digest('hex')
  const canonical = `POST\n${PATH}\n${ts}\n${bodyHash}`
  const sig = crypto.createHmac('sha256', clientSecret).update(canonical).digest('hex')

  const r = await fetch(`${apiBase}${PATH}`, {
    method: 'POST',
    headers: {
      'User-Agent': 'OrchexaBFF/1.0 (Next.js)',
      'X-Orchexa-Client-Id': clientId,
      'X-Orchexa-Timestamp': ts,
      'X-Orchexa-Signature': sig,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!r.ok) {
    const errText = await r.text()
    throw new Error(`Orchexa create session failed: ${r.status} ${errText}`)
  }

  return r.json() as Promise<{ session_token: string; conversation_id: string }>
}

'use client'

import { useEffect } from 'react'

declare global {
  interface Window {
    VoiceAgent?: {
      init: (opts: { sessionToken: string; apiUrl: string }) => void
      destroy?: () => void
      on?: (event: string, cb: (payload?: unknown) => void) => void
    }
  }
}

export function OrchexaWidget() {
  useEffect(() => {
    const SDK_URL = process.env.NEXT_PUBLIC_ORCHEXA_SDK_URL || 'https://api.orchexa.io/sdk/voice-agent.js'
    const API_URL = process.env.NEXT_PUBLIC_ORCHEXA_API_BASE || 'https://api.orchexa.io'
    if (!SDK_URL || !API_URL) return

    let sessionToken: string | null = null

    fetch('/api/ai/bootstrap', { method: 'POST', credentials: 'include' })
      .then((r) => {
        if (!r.ok) {
          throw new Error(`Bootstrap failed with status ${r.status}`)
        }
        return r.json()
      })
      .then((data) => {
        if (!data || !data.session_token) {
          throw new Error('No session_token returned from /api/ai/bootstrap')
        }
        sessionToken = data.session_token
        return loadSdk(SDK_URL)
      })
      .then(() => {
        if (!sessionToken) return
        window.VoiceAgent?.init({ sessionToken, apiUrl: API_URL })
        window.VoiceAgent?.on?.('error', (err) =>
          console.error('[OrchexaWidget]', err)
        )
      })
      .catch((e) => console.error('[OrchexaWidget] init failed', e))

    return () => {
      try {
        window.VoiceAgent?.destroy?.()
      } catch {
        /* noop */
      }
    }
  }, [])

  return null
}

function loadSdk(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const id = 'voice-agent-sdk'
    const existing = document.getElementById(id) as HTMLScriptElement | null
    if (existing) {
      if (window.VoiceAgent) return resolve()
      existing.addEventListener('load', () => resolve(), { once: true })
      return
    }
    const s = document.createElement('script')
    s.id = id
    s.src = src
    s.async = true
    s.onload = () => resolve()
    s.onerror = () => reject(new Error(`SDK failed: ${src}`))
    document.body.appendChild(s)
  })
}

"use client";

import Link from "next/link"
